def max_occurrences_of_01(S):
    n = len(S)
    even_zeros = 0
    even_ones = 0
    odd_zeros = 0
    odd_ones = 0

    for i in range(n):
        if i % 2 == 0:
            if S[i] == '0':
                even_zeros += 1
            else:
                even_ones += 1
        else:
            if S[i] == '0':
                odd_zeros += 1
            else:
                odd_ones += 1

    # Try to maximize the number of '01' substrings by swapping
    # We can swap pairs of characters of the same parity
    # The maximum number of '01' substrings is determined by the smaller of
    # the counts of 0s and 1s in even and odd positions
    max_swaps = min(even_zeros + odd_ones, even_ones + odd_zeros)

    return max_swaps

